package com.nexuscore.awakenedrealms;
import android.content.Context;import android.graphics.*;import android.util.AttributeSet;import android.view.View;import java.util.*;
public final class SystemGraphView extends View{private final Paint p=new Paint(1);private final ArrayDeque<Integer> samples=new ArrayDeque<>();public SystemGraphView(Context c,AttributeSet a){super(c,a);p.setStrokeWidth(5);p.setStrokeCap(Paint.Cap.ROUND);}public void push(int n){if(samples.size()>=30)samples.removeFirst();samples.addLast(n);invalidate();}@Override protected void onDraw(Canvas c){super.onDraw(c);p.setColor(Color.rgb(94,231,196));p.setStyle(Paint.Style.STROKE);Path path=new Path();int i=0,max=10;for(int v:samples)max=Math.max(max,v);for(int v:samples){float x=samples.size()<2?0:i*(getWidth()/(float)(samples.size()-1));float y=getHeight()-18-(getHeight()-36)*(v/(float)max);if(i++==0)path.moveTo(x,y);else path.lineTo(x,y);}c.drawPath(path,p);p.setColor(Color.rgb(38,72,91));c.drawLine(0,getHeight()-16,getWidth(),getHeight()-16,p);}}
